<script setup>
import { computed,onMounted,ref } from 'vue';import { api } from '../api/ehr';import { useAuthStore } from '../stores/auth'
const auth=useAuthStore(),jobs=ref([]),candidates=ref([]),tab=ref(0);const allowed=computed(()=>['ADMIN','HR'].includes(auth.user?.role));const jobLabels={OPEN:'招聘中',DRAFT:'草稿',CLOSED:'已关闭'};const stageLabels={APPLIED:'已投递',SCREENING:'筛选中',INTERVIEW:'面试中',OFFER:'已发 Offer',HIRED:'已录用',REJECTED:'已淘汰'}
onMounted(async()=>{if(allowed.value)[jobs.value,candidates.value]=await Promise.all([api.jobs(),api.candidates()])})
</script>
<template><div class="page safe-top"><van-nav-bar title="招聘管理" left-arrow @click-left="$router.back()"/><section v-if="!allowed" class="card empty">招聘信息仅人事与管理员可查看</section><template v-else><van-tabs v-model:active="tab" color="#7b4a35"><van-tab title="招聘职位"><section v-for="job in jobs" :key="job.id" class="card job"><div class="row"><b>{{job.title}}</b><span class="tag">{{jobLabels[job.status]}}</span></div><p>{{job.description}}</p><div class="muted">{{job.departmentName}} · 需求 {{job.headcount}} 人 · {{job.publishDate}}</div></section><div v-if="!jobs.length" class="empty">暂无招聘职位</div></van-tab><van-tab title="候选人"><section v-for="person in candidates" :key="person.id" class="card candidate"><div class="avatar">{{person.name.slice(0,1)}}</div><div><div class="row"><b>{{person.name}}</b><span class="tag">{{stageLabels[person.stage]}}</span></div><p>{{person.jobTitle}} · {{person.source}}</p><div class="muted">{{person.phone}} · {{person.appliedDate}}</div></div></section><div v-if="!candidates.length" class="empty">暂无候选人</div></van-tab></van-tabs></template></div></template>
<style scoped>.van-nav-bar{background:transparent;margin:-8px -16px 8px}.van-tabs{background:transparent}.row{display:flex;justify-content:space-between;gap:12px}.job p,.candidate p{color:#65554d;font-size:13px;line-height:1.6}.candidate{display:flex;gap:13px}.candidate>div:last-child{flex:1}.avatar{width:44px;height:44px;border-radius:14px;background:#f1e5dc;color:var(--brand);display:grid;place-items:center;font-weight:700}</style>
